#include <stdio.h>
#include <stdlib.h>

int main(void) {
    srand(5);
    int secret = rand() % 100 + 1;
    int guesses[3] = {50, 75, 62};
    int times = 0;

    while (times < 3) {
        int g = guesses[times];
        times++;
        if (g ____ secret) {
            printf("猜 %d：小了\n", g);
        } else if (g ____ secret) {
            printf("猜 %d：大了\n", g);
        } else {
            printf("猜 %d：猜中啦\n", g);
            return 0;
        }
    }
    printf("没猜中\n");
    return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
    time_t fixed = 1700000000L;
    struct tm *t = gmtime(&fixed);

    printf("%d-%02d-%02d\n", t->tm_year + 1900, t->tm_mon + 1, t->tm_mday);
    printf("一年里的第 %d 天\n", t->tm_yday + 1);
    printf("比 2023 年开年更晚吗？%s\n", fixed > 1672531200L ? "是" : "不是");
    return 0;
}

